layout.layoutData:
log.debug("settings --> " + settings.describe() + ", " + settings.seriesNames);

// Setting up series names from the datasource parameter settings
var seriesNames = new Array();
if (settings.seriesNames != null)
  seriesNames = settings.seriesNames.split(",");

// Keeping an index of what the start index of the IC is according
// to this datasource. Used if seriesNames are entered manually on
// the datasource transformation.
var seriesIndex = 0;
// at first processing integration connections
for (var icidx = 0; icidx < settings.ics.arrayLength; icidx++)
{
  log.debug("ic name is " + settings.ics[icidx]);

  // Find and execute the IntegrationComponent
  var ic = IntegrationComponent.getByName(settings.ics[icidx]);
  ic.execute();
  // log.debug("resultArray is " + ic.resultArray.describe());
  if (typeof icresults != 'undefined')
    icresults[icresults.arrayLength] = ic.resultArray;

  var records = ic.resultArray[0].record;
  // log.debug("records is " + records);
  if (records) {
    addDataFromRecords(records);
  }
}

// processing integration services
for (var idx = 0; idx < settings.services.arrayLength; idx++) {
  log.debug("Service name is " + settings.services[idx].name);
  var resultMap = settings.services[idx].execute();
  var result = resultMap.get("results");
  var records = result.record;
  log.debug("records is " + records);
  if (records) {
    addDataFromRecords(records);
  }
}

function addDataFromRecords(records) {
  for (var i = 0; i < records.length; i++) {
    var record = records[i];
    var columns = record.column;
    var labelValue = columns[0].getText();
    log.debug("columns is " + columns);
    // For each column besides the first one,
    for (var col = 1; col < columns.length; col++) {
      var seriesName = seriesNames[col - 1];
      log.debug("seriesNames -- " + seriesNames + "," + seriesName);
      if (seriesName == null) {
        seriesName = columns[col].getAttribute("name");
        seriesNames[col - 1] = seriesName;
      }
      log.debug("seriesNames -- after -- " + seriesNames + "," + seriesName);
      var displayValue = columns[col].getText();
      if (isNaN(displayValue))
        throw "display value for service '" + settings.services[idx].name + "', row #" + i + "[" + labelValue + "], column #" + (col - 1) +
              "[" + seriesName + "] is not a number (was: '" + displayValue + "')";

      log.debug("adding " + seriesName + ", " + labelValue + ", " + displayValue);
      addDataToSeries(seriesName, findLabelId(labelValue), displayValue);
    }
  }
}
